<body>
    <div class="container">
        <div class="header">
            <h1 style="font-size: 20px; margin-bottom: 4px;">حجز موعد</h1>
            <div class="doctor-name">د. فاطمة المنصوري</div>
        </div>

        <div class="calendar-header">
            <button class="nav-arrow" id="prevMonth">&#8249;</button>
            <div class="month-year" id="monthYear">أكتوبر 2023</div>
            <button class="nav-arrow" id="nextMonth">&#8250;</button>
        </div>

        <div class="weekdays">
            <div class="weekday">س</div>
            <div class="weekday">أ</div>
            <div class="weekday">أ</div>
            <div class="weekday">أ</div>
            <div class="weekday">أ</div>
            <div class="weekday">أ</div>
            <div class="weekday">أ</div>
        </div>

        <div class="days-grid" id="daysGrid"></div>

        <div class="time-slots">
            <h3>اختر وقتًا</h3>
            <div class="slots-container" id="slotsContainer"></div>
        </div>

        <button class="confirm-btn" id="confirmBtn" disabled>تأكيد الحجز</button>
    </div>

    <script>
        const arabicMonths = [
            "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
            "يوليو", "أغسطس", "سبتممبر", "أكتوبر", "نوفمبر", "ديسمبر"
        ];

        const arabicWeekdays = ["س", "أ", "أ", "أ", "أ", "أ", "أ"];

        let currentDate = new Date();
        let selectedDate = null;
        let selectedSlot = null;

        const monthYearEl = document.getElementById("monthYear");
        const daysGridEl = document.getElementById("daysGrid");
        const slotsContainerEl = document.getElementById("slotsContainer");
        const confirmBtn = document.getElementById("confirmBtn");
        const prevMonthBtn = document.getElementById("prevMonth");
        const nextMonthBtn = document.getElementById("nextMonth");

        function renderCalendar() {
            const year = currentDate.getFullYear();
            const month = currentDate.getMonth();

            monthYearEl.textContent = `${arabicMonths[month]} ${year}`;

            daysGridEl.innerHTML = "";

            const firstDay = new Date(year, month, 1);
            const lastDay = new Date(year, month + 1, 0);
            const daysInMonth = lastDay.getDate();

            // Get the day of week (0=Sunday, 1=Monday, ..., 6=Saturday)
            let startDay = firstDay.getDay();
            // Convert to Saturday-based week (Saturday=0, Sunday=1, ..., Friday=6)
            startDay = (startDay + 1) % 7;

            // Add empty cells for days from previous month
            for (let i = 0; i < startDay; i++) {
                const emptyDay = document.createElement("div");
                emptyDay.className = "day other-month";
                emptyDay.innerHTML = '<div class="day-number"></div>';
                daysGridEl.appendChild(emptyDay);
            }

            // Add days of current month
            for (let day = 1; day <= daysInMonth; day++) {
                const dayEl = document.createElement("div");
                dayEl.className = "day";
                dayEl.innerHTML = `<div class="day-number">${day}</div>`;

                const today = new Date();
                if (day === today.getDate() &&
                    month === today.getMonth() &&
                    year === today.getFullYear()) {
                    dayEl.classList.add("today");
                }

                dayEl.addEventListener("click", () => {
                    document.querySelectorAll(".day").forEach(d => d.classList.remove("selected"));
                    dayEl.classList.add("selected");
                    selectedDate = new Date(year, month, day);
                    renderTimeSlots();
                });

                daysGridEl.appendChild(dayEl);
            }

            // Fill remaining cells with next month's days
            const totalCells = startDay + daysInMonth;
            const remainingCells = Math.ceil(totalCells / 7) * 7 - totalCells;
            for (let i = 1; i <= remainingCells; i++) {
                const nextDay = document.createElement("div");
                nextDay.className = "day other-month";
                nextDay.innerHTML = `<div class="day-number">${i}</div>`;
                daysGridEl.appendChild(nextDay);
            }
        }

        function renderTimeSlots() {
            slotsContainerEl.innerHTML = "";
            selectedSlot = null;
            confirmBtn.disabled = true;

            const times = [];
            for (let h = 9; h <= 12; h++) {
                for (let m = 0; m < 60; m += 30) {
                    if (h === 12 && m > 0) break;
                    const hourStr = h.toString().padStart(2, "0");
                    const minStr = m.toString().padStart(2, "0");
                    times.push(`${hourStr}:${minStr}`);
                }
            }

            times.forEach(time => {
                const slotEl = document.createElement("div");
                slotEl.className = "slot";
                slotEl.textContent = time;
                slotEl.addEventListener("click", () => {
                    document.querySelectorAll(".slot").forEach(s => s.classList.remove("selected"));
                    slotEl.classList.add("selected");
                    selectedSlot = time;
                    confirmBtn.disabled = false;
                });
                slotsContainerEl.appendChild(slotEl);
            });
        }

        prevMonthBtn.addEventListener("click", () => {
            currentDate.setMonth(currentDate.getMonth() - 1);
            renderCalendar();
        });

        nextMonthBtn.addEventListener("click", () => {
            currentDate.setMonth(currentDate.getMonth() + 1);
            renderCalendar();
        });

        confirmBtn.addEventListener("click", () => {
            if (selectedDate && selectedSlot) {
                alert(`تم حجز موعد في ${selectedDate.toLocaleDateString('ar-EG')} الساعة ${selectedSlot}`);
            }
        });

        // Initialize
        renderCalendar();
    </script>
</body>
</html>
